      - run: sudo apt install rename
      - name: Rename files
        run: |
            rename 's/:/-/g' map/*
            rename 's/:/-/g' out_cmin/*
            rename 's/:/-/g' out/default/crashes/*
      - name: Upload updated corpus
        uses: actions/upload-artifact@v4
        with:
